using System.Text.Json;
namespace LeoLauncher;
static class DesktopToolsTests
{
    sealed class Sampler:IComputerSampler{public int Calls;public bool Detail,Fail;public ManualResetEventSlim? Gate;public ComputerSnapshot Read(bool detail,CancellationToken token){Calls++;Detail=detail;Gate?.Wait(token);if(Fail)throw new IOException("isolated sampling failure");token.ThrowIfCancellationRequested();return Snapshot(DateTimeOffset.Now,25);}}
    static ComputerSnapshot Snapshot(DateTimeOffset time,double? cpu)=>new(time,cpu,8L<<30,3L<<30,1024,2048,10L<<30,[new(123,1,"fixture-process",5,1024),new(456,1,"fixture-memory",1,4096)]);
    static IEnumerable<Control> Walk(Control root){yield return root;foreach(Control child in root.Controls)foreach(var item in Walk(child))yield return item;}
    public static void Run(string report){Directory.CreateDirectory(Path.GetDirectoryName(report)!);using var ui=new Form{Opacity=0,ShowInTaskbar=false};ui.Shown+=async(_,_)=>{var c=new Dictionary<string,bool>();try{await Check(Path.GetDirectoryName(report)!,c);File.WriteAllText(report,JsonSerializer.Serialize(new{ok=c.Values.All(v=>v),checks=c,external_processes_started=0,mail_contents_read=0,model_api_requests=0},new JsonSerializerOptions{WriteIndented=true}));}catch(Exception e){File.WriteAllText(report,JsonSerializer.Serialize(new{ok=false,error=e.ToString(),checks=c}));}finally{ui.Close();}};Application.Run(ui);}
    static async Task Check(string folder,Dictionary<string,bool> c)
    {
        c["cpu_delta_normalized"]=WindowsComputerSampler.CpuPercent(100,25)==75;c["invalid_cpu_not_zero"]=WindowsComputerSampler.CpuPercent(0,0)==null&&WindowsComputerSampler.CpuPercent(100,101)==null;c["network_reset_and_sleep_discarded"]=WindowsComputerSampler.Rate(100,200,5)==null&&WindowsComputerSampler.Rate(300,100,61)==null&&WindowsComputerSampler.Rate(300,100,2)==100;
        var rules=new SustainedResourceAlert();var t=DateTimeOffset.Now;bool quiet=true;for(int i=0;i<6;i++)quiet&=rules.Check(Snapshot(t.AddSeconds(i*5),95))==null;c["short_spike_silent"]=quiet;c["sustained_load_warns_once"]=rules.Check(Snapshot(t.AddSeconds(30),95))!=null&&rules.Check(Snapshot(t.AddSeconds(35),95))==null;rules.Reset();c["sleep_does_not_count_as_sustained"]=rules.Check(Snapshot(t.AddHours(1),95))==null&&rules.Check(Snapshot(t.AddHours(2),95))==null;
        var sampler=new Sampler();bool enabled=true,visible=false,alerts=false;int notices=0;using(var monitor=new ComputerMonitor(sampler,()=>enabled,()=>alerts,()=>visible,_=>notices++)){
            monitor.Configure();await monitor.Tick();c["closed_default_no_sampling"]=!monitor.Active&&sampler.Calls==0;visible=true;monitor.Configure();await monitor.Tick();c["visible_samples_details"]=monitor.Active&&sampler.Detail&&monitor.Current!=null;visible=false;monitor.Configure();c["closing_stops_sampling_without_alerts"]=!monitor.Active;alerts=true;monitor.Configure();await monitor.Tick();c["background_alerts_sample_aggregate_only"]=monitor.Active&&!sampler.Detail;enabled=false;monitor.Configure();int before=sampler.Calls;await monitor.Tick();c["disabled_stops_and_cannot_restart"]=!monitor.Active&&sampler.Calls==before&&notices==0;
        }
        var broken=new Sampler{Fail=true};using(var monitor=new ComputerMonitor(broken,()=>true,()=>false,()=>true,_=>{})){monitor.Configure();await monitor.Tick();c["sampling_failure_isolated"]=!monitor.Active&&monitor.Current==null;broken.Fail=false;monitor.Configure();await monitor.Tick();c["explicit_reopen_can_retry_sampling"]=monitor.Active&&monitor.Current!=null;}
        c["sampling_activity_released"]=ModuleActivities.Snapshot().All(a=>a.Module!="system-monitor");
        var delayed=new Sampler{Gate=new(false)};using(var monitor=new ComputerMonitor(delayed,()=>true,()=>false,()=>true,_=>{})){monitor.Configure();var pending=monitor.Tick();for(int i=0;i<100&&delayed.Calls==0;i++)await Task.Delay(10);monitor.Dispose();await pending;c["dispose_discards_inflight_result"]=monitor.Current==null;}delayed.Gate.Dispose();
        var prefs=new Preferences{ApplicationIndexing=false,SystemMonitorModule=true,DesktopMailModule=true};int runs=0;var module=new DesktopToolModule("system-monitor","电脑状态",()=>prefs.SystemMonitorModule,["system_open","system_snapshot"],(_,_)=>{runs++;return Task.FromResult(new ActionPayload("fixture",Evidence:"window-shown"));});using var bus=new ActionDispatcher(prefs,(_,_,_)=>throw new Exception("no legacy"),new ExtensionStore(Path.Combine(folder,"empty-extensions")));bus.Registry.Register(module);EntryContributions.Bind(prefs,bus.Registry,bus);c["registered_contract_valid"]=ModuleContracts.Snapshot(module).Contract.Enablement=="optional";c["shortcut_and_search_from_contribution"]=EntryContributions.ReadModules(prefs).Buttons.Single().Id=="system-monitor/open";c["gateway_uses_unified_execution"]=(await EntryContributions.ExecuteModule(prefs,"system-monitor/open","fixture")).Status=="succeeded"&&runs==1;c["extra_parameters_rejected"]=(await bus.ExecuteStructuredAsync(new("leo-action/1","system_open",JsonSerializer.SerializeToElement(new{path="forbidden"})))).Status=="failed"&&runs==1;
        prefs.SystemMonitorModule=false;bool rejected=false;try{await EntryContributions.ExecuteModule(prefs,"system-monitor/open","stale");}catch(InvalidOperationException){rejected=true;}c["disabled_contribution_old_click_rejected"]=rejected&&runs==1&&EntryContributions.ReadModules(prefs).Buttons.Length==0;
        c["clear_commands_stay_local"]=QuickRouter.Route("看看电脑状态").Value=="system_open"&&QuickRouter.Route("打开邮箱").Value=="mail_client_open"&&QuickRouter.Route("打开任务管理器").Value=="system_taskmanager";
        var profile=UsageProfiles.Capture(prefs,"test",bus.Extensions);var pure=UsageProfiles.Prepare(UsageProfiles.Templates()[0],prefs,bus.Extensions);c["profiles_capture_new_flags_and_companion_disables"]=profile.Modules.ContainsKey("system-monitor")&&profile.Modules["mail-client"]&&!pure.SystemMonitorModule&&!pure.DesktopMailModule;c["old_preferences_do_not_enable_new_modules"]=!JsonSerializer.Deserialize<Preferences>("{}")!.SystemMonitorModule&&!JsonSerializer.Deserialize<Preferences>("{}")!.DesktopMailModule;
        using(var modules=new ModulesView(prefs,true)){var draft=new Preferences();modules.Apply(draft,false);c["settings_preserve_new_module_switches"]=draft.DesktopMailModule&&!draft.SystemMonitorModule;}
        bool show=true;using(var monitor=new ComputerMonitor(new Sampler(),()=>true,()=>false,()=>show,_=>{})){using var form=new ComputerStatusForm(monitor,prefs,change=>change(prefs),_=>Task.CompletedTask);form.StartPosition=FormStartPosition.Manual;form.Location=new(-19000,-19000);form.Show();monitor.Configure();await monitor.Tick();c["monitor_ui_shows_fake_values_and_process"]=Walk(form).OfType<ListView>().Single().Items[0].Text=="fixture-process"&&Walk(form).OfType<Label>().Any(l=>l.Text.Contains("25.0%"));var list=Walk(form).OfType<ListView>().Single();typeof(ListView).GetMethod("OnColumnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(list,[new ColumnClickEventArgs(3)]);c["memory_column_sorts_actual_rows"]=list.Items[0].Text=="fixture-memory";typeof(ListView).GetMethod("OnColumnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(list,[new ColumnClickEventArgs(2)]);c["cpu_column_restores_cpu_order"]=list.Items[0].Text=="fixture-process";using var png=new Bitmap(form.Width,form.Height);form.DrawToBitmap(png,new Rectangle(Point.Empty,form.Size));png.Save(Path.Combine(folder,"computer-status.png"));form.Close();show=false;monitor.Configure();c["window_close_unsubscribes_and_stops"]=!monitor.Active;}
        using(var form=new MailClientForm(prefs,change=>change(prefs),()=>Task.CompletedTask,true)){form.StartPosition=FormStartPosition.Manual;form.Location=new(-19000,-19000);form.Show();c["mail_ui_has_no_credential_fields"]=Walk(form).OfType<TextBox>().Count()==1&&Walk(form).OfType<Label>().Any(l=>l.Text.Contains("不读取邮件"));using var png=new Bitmap(form.Width,form.Height);form.DrawToBitmap(png,new Rectangle(Point.Empty,form.Size));png.Save(Path.Combine(folder,"mail-client.png"));form.Close();}
        var actual=new WindowsComputerSampler();var real=await Task.Run(()=>actual.Read(false,CancellationToken.None));c["local_aggregate_smoke_without_process_or_mail_payload"]=real.TotalMemory>0&&real.AvailableMemory>=0&&real.AvailableMemory<=real.TotalMemory&&real.Processes.Length==0;
        c["all_new_window_activity_released"]=ModuleActivities.Snapshot().All(a=>a.Module!="system-monitor");
    }
